<?php /** @var array<string,mixed> $v */ /** @var list<array<string,mixed>> $rows */ ?>
<div class="page-head"><div><p class="eyebrow">Policy acceptance</p><h1><?= e($v['doc_title']) ?> · v<?= e($v['version_no']) ?></h1></div><a class="btn btn-ghost" href="/admin/compliance/acceptance">&larr; All versions</a></div>
<div class="panel"><p>Status: <strong><?= e(ucfirst((string) $v['status'])) ?></strong> · deadline <?= $v['accept_by'] ? e(local_date((string) $v['accept_by'])) : '—' ?></p>
    <?php if ($v['status'] === 'published') : ?>
    <form method="post" action="/admin/compliance/acceptance/<?= e($v['id']) ?>/remind" class="inline-form" data-confirm="Email a reminder to every client who has not accepted?"><?= csrf_field() ?><button class="btn btn-ghost btn-sm" type="submit">Send reminders</button></form>
    <form method="post" action="/admin/compliance/acceptance/<?= e($v['id']) ?>/extend" class="inline-form"><?= csrf_field() ?><label for="nd" class="sr-only">New deadline</label><input id="nd" name="accept_by" type="date" required><button class="btn btn-ghost btn-sm" type="submit">Move the deadline</button></form>
    <?php endif; ?></div>
<div class="panel"><div class="table-wrap"><table class="table"><thead><tr><th>Client</th><th>Status</th><th>Decided</th><th>Notified</th><th>Record on their behalf</th></tr></thead><tbody>
<?php foreach ($rows as $r) : ?><tr><td><?= e($r['name']) ?><br><span class="muted small"><?= e($r['email']) ?></span></td>
    <td><span class="badge badge-d-<?= $r['state'] === 'accepted' ? 'confirmed' : ($r['state'] === 'pending' ? 'request' : 'cancelled') ?>"><?= e(ucfirst((string) $r['state'])) ?></span><?= $r['method'] ? ' <span class="muted small">' . e($r['method']) . '</span>' : '' ?></td>
    <td><?= $r['decided_at'] ? e(local_time($r['decided_at'])) : '—' ?></td><td><?= $r['notified_at'] ? e(local_time($r['notified_at'])) : '—' ?></td>
    <td><?php if ($r['state'] !== 'accepted' && $v['status'] === 'published') : ?><form method="post" action="/admin/compliance/acceptance/<?= e($v['id']) ?>/record" class="inline-form"><?= csrf_field() ?><input type="hidden" name="user" value="<?= e($r['id']) ?>"><label class="sr-only" for="n<?= e($r['id']) ?>">How it was given</label><input id="n<?= e($r['id']) ?>" name="note" placeholder="e.g. signed on paper 3 Nov" maxlength="250" required><label class="sr-only" for="p<?= e($r['id']) ?>">Your password</label><input id="p<?= e($r['id']) ?>" name="confirm_password" type="password" placeholder="Your password" required><button class="btn btn-ghost btn-sm" type="submit">Record</button></form><?php else : ?>—<?php endif; ?></td></tr><?php endforeach; ?>
<?php if ($rows === []) : ?><tr><td colspan="5" class="muted">No clients yet.</td></tr><?php endif; ?></tbody></table></div></div>
